public void avaInitializeLabelFromWorkLines(WHSWorkLine _workLine, EcoResReleasedProductUnitConverter _converter)
{
    WHSWorkInventTrans  avaWHSWorkInventTrans;

    if (_workLine.WorkId
     && _workLine.LineNum)
    {
        select sum(Qty) from avaWHSWorkInventTrans
            where avaWHSWorkInventTrans.WorkId  == _workLine.WorkId
               && avaWHSWorkInventTrans.LineNum == _workLine.LineNum
               && avaWHSWorkInventTrans.ItemId  == _workLine.ItemId;

        label.AVAPickedQty = avaWHSWorkInventTrans.Qty;

        if (!label.AVAPickedQty)
        {
            select sum(Qty) from avaWHSWorkInventTrans
                where avaWHSWorkInventTrans.WorkId  == _workLine.WorkId
                   && avaWHSWorkInventTrans.LineNum == _workLine.LineNum;

            label.AVAPickedQty = avaWHSWorkInventTrans.Qty;
        }
    }
}
